import sys

def is_regular_sequence(s, k):
    n = len(s)
    if n < 2 * k + 1:
        return False
    for i in range(1, n // 2 + 1):
        if n % (2 * i) != 2 * k + 1:
            continue
        A = s[:i]
        B = s[i:i + i]
        pattern = A + B
        if pattern * ((n - 2 * k - 1) // (2 * i) + 1) == s[:n - 2 * k - 1]:
            return True
    return False

